const MM_TO_IN = 25.4;
const TEMPLATE_L = 270.0; // mm (Lid and inner box nominal length)
const TEMPLATE_W = 260.0; // mm (Tray base and lid nominal width)
const TEMPLATE_H = 62.0;  // mm (Side wall height)

export function transformPoint(origX, origY, L_UI = 270.0, W_UI = 260.0, H_UI = 62.0) {
  const BASE_L = TEMPLATE_L;
  const BASE_W = TEMPLATE_W;
  const BASE_H = TEMPLATE_H;

  const sH = H_UI / BASE_H;
  const sL = L_UI / BASE_L;
  const sW = W_UI / BASE_W;

  let x = origX;
  if (origX <= 68.5) {
    x = origX * sH;
  } else if (origX <= 73.5) {
    x = 68.5 * sH + (origX - 68.5);
  } else if (origX <= 135.5) {
    x = 68.5 * sH + 5.0 + (origX - 73.5) * sH;
  } else if (origX <= 140.5) {
    x = (68.5 + 62.0) * sH + 5.0 + (origX - 135.5);
  } else if (origX <= 410.5) {
    x = (68.5 + 62.0) * sH + 10.0 + (origX - 140.5) * sL;
  } else if (origX <= 415.5) {
    x = (68.5 + 62.0) * sH + 10.0 + 270.0 * sL + (origX - 410.5);
  } else if (origX <= 477.5) {
    x = (68.5 + 62.0) * sH + 15.0 + 270.0 * sL + (origX - 415.5) * sH;
  } else if (origX <= 482.5) {
    x = (68.5 + 2 * 62.0) * sH + 15.0 + 270.0 * sL + (origX - 477.5);
  } else {
    x = (68.5 + 2 * 62.0) * sH + 20.0 + 270.0 * sL + (origX - 482.5) * sH;
  }

  let y = origY;
  if (origY <= 67.0) {
    y = 67.0 * sH - (67.0 - origY) * sH;
  } else if (origY <= 328.5) {
    y = 67.0 * sH + (origY - 67.0) * sW;
  } else if (origY <= 390.5) {
    y = 67.0 * sH + 261.5 * sW + (origY - 328.5) * sH;
  } else if (origY <= 650.5) {
    y = (67.0 + 62.0) * sH + 261.5 * sW + (origY - 390.5) * sW;
  } else {
    y = (67.0 + 62.0) * sH + (261.5 + 260.0) * sW + (origY - 650.5) * sH;
  }

  return { x, y };
}

