const BLEED_SEGMENTS = [[98.0,70.9999995,117.77677,70.9999995],[117.77677,70.9999995,88.159599,81.7797695],[75.0,100.5736235,75.0,294.9263895],[88.159599,313.7202095,117.77681,324.4999995],[117.77681,324.4999995,28.0,324.4999995],[28.0,324.4999995,28.0,386.9999995],[28.0,386.9999995,3.75,386.9999995],[3.75,386.9999995,3.75,439.6148395],[3.75,439.6148395,0.0,441.1148395],[0.0,441.1148395,0.0,495.8851595],[0.0,495.8851595,3.75,497.3851595],[3.75,497.3851595,3.75,543.6148095],[3.75,543.6148095,0.0,545.1148095],[0.0,545.1148095,0.0,599.8851895],[0.0,599.8851895,3.75,601.3851895],[3.75,601.3851895,3.75,653.9999995],[3.75,653.9999995,29.0,653.9999995],[29.0,653.9999995,29.0,715.9999995],[29.0,715.9999995,522.0,715.9999995],[522.0,715.9999995,522.0,653.9999995],[522.0,653.9999995,547.25,653.9999995],[547.25,653.9999995,547.25,601.3851895],[547.25,601.3851895,551.0,599.8851895],[551.0,599.8851895,551.0,545.1148095],[551.0,545.1148095,547.25,543.6148095],[547.25,543.6148095,547.25,497.3851595],[547.25,497.3851595,551.0,495.8851595],[551.0,495.8851595,551.0,441.1148395],[551.0,441.1148395,547.25,439.6148395],[547.25,439.6148395,547.25,386.9999995],[547.25,386.9999995,523.0,386.9999995],[523.0,386.9999995,523.0,324.4999995],[523.0,324.4999995,433.22321,324.4999995],[433.22321,324.4999995,462.84042,313.7202095],[476.0,294.9263895,476.0,100.5736235],[462.84042,81.7797695,433.22324,70.9999995],[433.22324,70.9999995,453.0,70.9999995],[416.10074,2.5296862,413.57108,0.0],[413.57108,0.0,137.42894,0.0],[137.42894,0.0,134.89925,2.5296864],[98.0,70.9999995,98.0,70.9999995],"M88.159599,81.7797695 C84.20914433,83.2176155 81.02826433,85.65839117 78.616959,89.1020965 ","M78.616959,89.1020965 C76.20564767,92.5458065 74.99999467,96.36964883 75,100.5736235 ","M75,294.9263895 C75,299.1303695 76.205653,302.95421283 78.616959,306.3979195 ","M78.616959,306.3979195 C81.028249,309.84160617 84.209129,312.2823695 88.159599,313.7202095 ","M462.84042,313.7202095 C466.79084,312.2823695 469.97171,309.84159617 472.38303,306.3978895 ","M472.38303,306.3978895 C474.79434333,302.95418283 476,299.1303495 476,294.9263895 ","M476,100.5736235 C476,96.36962883 474.79435333,92.5457865 472.38306,89.1020965 ","M472.38306,89.1020965 C469.97174,85.65839117 466.79086,83.2176155 462.84042,81.7797695 ","M453,70.9999995 C457.97054,70.9999995 462.21316333,69.24263983 465.72787,65.7279205 ","M465.72787,65.7279205 C469.24262333,62.21316983 471,57.97053083 471,53.0000035 ","M471,53.0000035 C471.00002,38.92297683 465.35404333,26.9442285 454.06207,17.0637585 ","M454.06207,17.0637585 C443.46685667,7.79294157 430.81308,2.9482508 416.10074,2.5296862 ","M134.89925,2.5296864 C120.18692333,2.9482528 107.533149,7.79294383 96.937927,17.0637595 ","M96.937927,17.0637595 C85.64597567,26.94421617 80,38.92296283 80,52.9999995 ","M80,52.9999995 C80,57.97056017 81.75735967,62.2132005 85.272079,65.7279205 ","M85.272079,65.7279205 C88.786799,69.24263983 93.02943933,70.9999995 98,70.9999995 "];

function transformSVGPath(pathStr, L, W, H, thickness) {
  return pathStr.replace(/([A-Za-z])([^A-Za-z]*)/g, (match, cmd, args) => {
    if (cmd.toUpperCase() === 'Z') return cmd;
    const nums = args.match(/-?\d*\.?\d+/g);
    if (!nums) return match;
    const newNums = [];
    for (let i = 0; i < nums.length; i += 2) {
      if (nums[i] !== undefined && nums[i+1] !== undefined) {
        const p = transformPoint(parseFloat(nums[i]), parseFloat(nums[i+1]), L, W, H, thickness);
        newNums.push(p.x + ',' + p.y);
      }
    }
    return cmd + newNums.join(' ');
  });
}

function buildLinePaths(segments, L, W, H, thickness) {
  return segments.map(seg => {
    if (Array.isArray(seg)) {
      const [x1, y1, x2, y2] = seg;
      const a = transformPoint(x1, y1, L, W, H, thickness);
      const b = transformPoint(x2, y2, L, W, H, thickness);
      return `M ${a.x},${a.y} L ${b.x},${b.y}`;
    } else {
      return transformSVGPath(seg, L, W, H, thickness);
    }
  });
}

function buildFoldLines(segments, L, W, H, thickness) {
  return segments.filter(s => Array.isArray(s)).map(([x1, y1, x2, y2]) => {
    const a = transformPoint(x1, y1, L, W, H, thickness);
    const b = transformPoint(x2, y2, L, W, H, thickness);
    return { x1: a.x, y1: a.y, x2: b.x, y2: b.y };
  });
}

export function generateCosmeticBoxBDieline({ L, W, H, T = 0.5, glueFlapWidth = 0.625, bleed = 0.125 }) {
  const isProbablyInches = Number(L) < 50;
  const nL = isProbablyInches ? Number(L) * MM_TO_IN : Number(L);
  const nW = isProbablyInches ? Number(W) * MM_TO_IN : Number(W);
  const nH = isProbablyInches ? Number(H) * MM_TO_IN : Number(H);
  const thickness = isProbablyInches ? (Number(T) || 0.0197) * MM_TO_IN : (Number(T) || 0.5);

  const rawCutPaths = buildLinePaths(CUT_SEGMENTS, nL, nW, nH, thickness);
  const rawFoldLines = buildFoldLines(FOLD_SEGMENTS, nL, nW, nH, thickness);
  const rawBleedPaths = buildLinePaths(BLEED_SEGMENTS, nL, nW, nH, thickness);

  const scaleFactor = isProbablyInches ? (1 / MM_TO_IN) : 1;

  const cutPaths = scaleFactor === 1 ? rawCutPaths : rawCutPaths.map(p => scalePathString(p, scaleFactor));
  const bleedPaths = scaleFactor === 1 ? rawBleedPaths : rawBleedPaths.map(p => scalePathString(p, scaleFactor));
  const foldLines = scaleFactor === 1 ? rawFoldLines : rawFoldLines.map(f => ({
    x1: f.x1 * scaleFactor,
    y1: f.y1 * scaleFactor,
    x2: f.x2 * scaleFactor,
    y2: f.y2 * scaleFactor
  }));

  let maxX = -Infinity, maxY = -Infinity, minX = Infinity, minY = Infinity;
  for (const seg of [...CUT_SEGMENTS, ...FOLD_SEGMENTS, ...BLEED_SEGMENTS]) {
    if (Array.isArray(seg)) {
      const [x1, y1, x2, y2] = seg;
      for (const p of [transformPoint(x1, y1, nL, nW, nH, thickness), transformPoint(x2, y2, nL, nW, nH, thickness)]) {
        const px = p.x * scaleFactor;
        const py = p.y * scaleFactor;
        if (px > maxX) maxX = px; if (py > maxY) maxY = py;
        if (px < minX) minX = px; if (py < minY) minY = py;
      }
    }
  }

  const x1 = transformPoint(73.5, 0, nL, nW, nH).x * scaleFactor;
  const x2 = transformPoint(135.5, 0, nL, nW, nH).x * scaleFactor;
  const x3 = transformPoint(415.5, 0, nL, nW, nH).x * scaleFactor;
  const x4 = transformPoint(477.5, 0, nL, nW, nH).x * scaleFactor;
  const x5 = transformPoint(551.0, 0, nL, nW, nH).x * scaleFactor;

  const yTop = transformPoint(0, 67.0, nL, nW, nH).y * scaleFactor;
  const yBot = transformPoint(0, 328.5, nL, nW, nH).y * scaleFactor;

  const result = {
    width: maxX, height: maxY, minX, minY,
    cutPaths, bleedPaths, foldLines,
    dimensions: { 
      L: Number(L), W: Number(W), H: Number(H), T: Number(T),
      x1, x2, x3, x4, x5, yTop, yBot,
      template: { L: TEMPLATE_L * scaleFactor, W: TEMPLATE_W * scaleFactor, H: TEMPLATE_H * scaleFactor }
    },
  };

  return result;
}

function scalePathString(pathStr, scale) {
  return pathStr.replace(/([A-Za-z])([^A-Za-z]*)/g, (match, cmd, args) => {
    if (cmd.toUpperCase() === 'Z') return cmd;
    const nums = args.match(/-?\d*\.?\d+/g);
    if (!nums) return match;
    const newNums = nums.map(n => (parseFloat(n) * scale).toFixed(5));
    let reconstructed = '';
    for (let i = 0; i < newNums.length; i += 2) {
      if (newNums[i] !== undefined && newNums[i+1] !== undefined) {
        reconstructed += (i > 0 ? ' ' : '') + newNums[i] + ',' + newNums[i+1];
      } else if (newNums[i] !== undefined) {
        reconstructed += (i > 0 ? ' ' : '') + newNums[i];
      }
    }
    return cmd + ' ' + reconstructed + ' ';
  });
}

if (typeof window !== "undefined") {
  window.generateCosmeticBoxBDieline = generateCosmeticBoxBDieline;
}

